.product-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: start;
}

.product-hero {
  width: 100%;
  aspect-ratio: 1;
  border-radius: 12px;
}

.product-info h1 {
  font-size: 2rem;
}

.product-price {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0.5rem 0;
}

.product-description {
  color: #666;
  line-height: 1.6;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.5rem;
  color: #666;
  text-decoration: none;
}

.skeleton-image {
  background: #e5e5e5;
  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text {
  height: 1rem;
  background: #e5e5e5;
  border-radius: 4px;
  margin: 0.5rem 1rem;
  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text.short {
  width: 60%;
}

.skeleton-text.large {
  height: 2rem;
  width: 70%;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ── View Transitions ─────────────────────────────────── */

/* Directional slide for page-level transitions */
@keyframes slide-in-from-right {
  from {
    opacity: 0;
    transform: translateX(60px);
  }
}

@keyframes slide-out-to-left {
  to {
    opacity: 0;
    transform: translateX(-60px);
  }
}

@keyframes slide-in-from-left {
  from {
    opacity: 0;
    transform: translateX(-60px);
  }
}

@keyframes slide-out-to-right {
  to {
    opacity: 0;
    transform: translateX(60px);
  }
}

/* Forward navigation: grid → detail */
::view-transition-old(page) {
  animation: slide-out-to-left 0.3s ease-in both;
}

::view-transition-new(page) {
  animation: slide-in-from-right 0.3s ease-out both;
}

/* Back navigation: detail → grid */
.back-navigation::view-transition-old(page) {
  animation: slide-out-to-right 0.3s ease-in both;
}

.back-navigation::view-transition-new(page) {
  animation: slide-in-from-left 0.3s ease-out both;
}

/* Shared element: product image morphs between thumbnail and hero */
::view-transition-group(product-image-*) {
  animation-duration: 0.35s;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

/* Suspense content reveal: fade in smoothly when content replaces skeleton */
@keyframes fade-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

::view-transition-new(product-details) {
  animation: fade-in 0.4s ease-out both;
}

::view-transition-old(product-details) {
  animation: fade-out 0.2s ease-in both;
}

@keyframes fade-out {
  to {
    opacity: 0;
  }
}

/* ── Reduced Motion ───────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0.01ms !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

